#include <iostream>
#include <cstdlib>

using namespace std;

int main()
{
    int a, x, y;
    cin >> a >> x >> y;

    if (abs(x) > a || y < 0 || y > 5 * a ||
        (abs(x) % a == 0 && x != 0) || y % a == 0)
        cout << -1 << endl;
    else if (y < 2 * a)
    {
        if (abs(x) < a / 2.0)
            cout << y / a + 1 << endl;
        else
            cout << -1 << endl;
    }
    else if (y < 3 * a)
    {
        if (x == 0)
            cout << -1 << endl;
        else if (x < 0)
            cout << 3 << endl;
        else
            cout << 4 << endl;
    }
    else if (y < 4 * a)
    {
        if (abs(x) < a / 2.0)
            cout << 5 << endl;
        else
            cout << -1 << endl;
    }
    else
    {
        if (x == 0)
            cout << -1 << endl;
        else if (x < 0)
            cout << 6 << endl;
        else
            cout << 7 << endl;
    }

    return 0;
}

